#include "rsr_private.h"
#include "status.h"
#include "prog.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/
 
/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*        I N L I N E   F U N C T I O N S   &   T E M P L A T E S           */
/*==========================================================================*/
void rsr_state_arm(void)
{ 
	if(RSR_CUR_TIME >= RSR_STOP_TO_REARM_TIMEOUT)
    {  
		if(!RSR_ENGINE_RUNNING  && !rsr_vars.ign && (prog_retrieve_option (FEAT_SECURE_LOCK) == SECURE_LOCK_DISABLE)) // only use standard disarm if Smart oem alarm control is disabled
		{
		  #if RSR_ARM_ENA == 1	
			rsr_arm (0) ; 
		  #endif
		}

		rsr_set_state (RSR_STATE_STOP) ;
	}
}
